        /// <summary>Rebuilds the source document from this snapshot alone: typed rows from their typed values and every other row or section from its retained source text. Semantically equal to the source (see SemanticJsonEquivalence). Null when the source returned no document.</summary>
        public string? ReconstructSourceDocument()
        {
            if (_documentPresent == false)
            {
                return null;
            }

            var buffer = new ArrayBufferWriter<byte>();
            using (var writer = new Utf8JsonWriter(buffer, new JsonWriterOptions { Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping }))
            {
                writer.WriteStartObject();
                foreach (SemanticSection section in Sections)
                {
                    writer.WritePropertyName(section.Name);
                    if (section.Raw is { } raw)
                    {
                        writer.WriteRawValue(raw.RawText, skipInputValidation: true);
                        continue;
                    }

                    writer.WriteStartArray();
                    foreach (SemanticSectionRow row in section.Rows)
                    {
                        if (row.Disposition != SemanticRowDisposition.Entity)
                        {
                            writer.WriteRawValue(row.Raw!.Value.RawText, skipInputValidation: true);
                            continue;
                        }

                        switch (section.Name)
                        {
                            case "model_invocation_summary":
                                WriteModelInvocationSummary(writer, _summary[row.EntityOrdinal!.Value]);
                                break;
                            case "model_invocations":
                                WriteModelInvocation(writer, _invocations[row.EntityOrdinal!.Value]);
                                break;
                            case "instruction_constructors":
                                WriteInstructionConstructor(writer, _constructors[row.EntityOrdinal!.Value]);
                                break;
                            case "instruction_segments":
                                WriteInstructionSegment(writer, _segments[row.EntityOrdinal!.Value]);
                                break;
                            case "instruction_inputs":
                                WriteInstructionInput(writer, _inputs[row.EntityOrdinal!.Value]);
                                break;
                            case "response_policies":
                                WriteResponsePolicy(writer, _responsePolicies[row.EntityOrdinal!.Value]);
                                break;
                            case "model_configuration":
                                WriteModelConfigurationValue(writer, _configurationValues[row.EntityOrdinal!.Value]);
                                break;
                            case "inactive_templates":
                                WriteInactiveTemplate(writer, _inactiveTemplates[row.EntityOrdinal!.Value]);
                                break;
                            case "model_invocation_findings":
                                WriteModelInvocationFinding(writer, _findings[row.EntityOrdinal!.Value]);
                                break;
                        }
                    }

                    writer.WriteEndArray();
                }

                writer.WriteEndObject();
            }

            return Encoding.UTF8.GetString(buffer.WrittenSpan);
        }

        private void WriteModelInvocationSummary(Utf8JsonWriter writer, ModelInvocationSummary entity)
        {
            writer.WriteStartObject();
            writer.WriteString("result_set", "model_invocation_summary");
            writer.WriteString("row_state", "ROW");
            writer.WriteString("capability_id", entity.CapabilityId);
            writer.WriteString("namespace_id", entity.NamespaceId);
            writer.WriteNumber("capability_pk", entity.CapabilityPk);
